    @Environment(AIProviderManager.self) private var providerManager
    @State private var showingAddProvider = false
    @State private var editingProvider: AIProviderConfig?

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            Text("Configure AI providers for margin notes and annotations")
                .foregroundStyle(.secondary)
                .font(.subheadline)

            if providerManager.providers.isEmpty {
                ContentUnavailableView(
                    "No AI Providers Configured",
                    systemImage: "cpu",
                    description: Text("Add an AI provider to enable margin notes and conversations")
                )
            } else {
                List {
                    ForEach(providerManager.providers) { provider in
                        ProviderRow(provider: provider)
                            .contentShape(Rectangle())
                            .onTapGesture {
                                editingProvider = provider
                            }
                    }
                    .onDelete(perform: deleteProviders)
                }
                .listStyle(.inset)
            }

            HStack {
                Button("Add Provider", systemImage: "plus") {
                    showingAddProvider = true
                }
                .buttonStyle(.borderedProminent)

                Spacer()

                if let activeName = providerManager.activeProviderName {
                    Label("Active: \(activeName)", systemImage: "checkmark.circle.fill")
                        .foregroundStyle(.green)
                }
            }
        }
        .padding()
        .sheet(isPresented: $showingAddProvider) {
            ProviderEditView(provider: nil, providerManager: providerManager)
        }
        .sheet(item: $editingProvider) { provider in
            ProviderEditView(provider: provider, providerManager: providerManager)
        }
    }

    private func deleteProviders(at offsets: IndexSet) {
        for index in offsets {
            let provider = providerManager.providers[index]
            try? providerManager.deleteProvider(provider)
        }
    }
}

