struct HighlightListRow: View {
    let item: HighlightWithBookInfo
    @State private var isHovered = false

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            // Book title and date header
            HStack(spacing: 8) {
                Image(systemName: "book.fill")
                    .font(.caption2)
                    .foregroundStyle(.blue)

                Text(item.bookTitle)
                    .font(.caption)
                    .fontWeight(.medium)
                    .foregroundStyle(.secondary)
                    .lineLimit(1)

                Spacer()

                Text(item.highlight.createdAt.relativeShort)
                    .font(.caption2)
                    .foregroundStyle(.tertiary)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 2)
                    .background(Color.secondary.opacity(0.1))
                    .clipShape(Capsule())
            }

            // Highlighted text preview with highlight indicator
            HStack(alignment: .top, spacing: 8) {
                Rectangle()
                    .fill(Color.yellow)
                    .frame(width: 3)
                    .clipShape(RoundedRectangle(cornerRadius: 1.5))

                Text(item.textPreview)
                    .font(.body)
                    .lineLimit(3)
                    .fixedSize(horizontal: false, vertical: true)
            }

            // Metadata badges with enhanced styling
            HStack(spacing: 6) {
                if item.hasAnnotation {
                    metadataBadge(
                        icon: "note.text",
                        text: "Note",
                        color: .blue
                    )
                }

                if item.threadCount > 0 {
                    metadataBadge(
                        icon: "bubble.left.and.bubble.right",
                        text: "\(item.threadCount)",
                        color: .purple
                    )
                }

                if item.messageCount > 0 {
                    metadataBadge(
                        icon: "message",
                        text: "\(item.messageCount)",
                        color: .green
                    )
                }

                Spacer()
            }
        }
        .padding(12)
        .background(
            RoundedRectangle(cornerRadius: 8)
                .fill(isHovered ? Color(.controlBackgroundColor) : Color.clear)
        )
        .overlay(
            RoundedRectangle(cornerRadius: 8)
                .stroke(Color.secondary.opacity(0.1), lineWidth: 1)
        )
        .onHover { hovering in
            withAnimation(.easeInOut(duration: 0.15)) {
                isHovered = hovering
            }
        }
    }

    private func metadataBadge(icon: String, text: String, color: Color) -> some View {
        HStack(spacing: 4) {
            Image(systemName: icon)
            Text(text)
        }
        .font(.caption2)
        .fontWeight(.medium)
        .padding(.horizontal, 8)
        .padding(.vertical, 4)
        .background(color.opacity(0.15))
        .foregroundColor(color)
        .clipShape(Capsule())
    }
}

