                .disabled(currentChapterIndex == 0)
                .accessibilityIdentifier("previousChapter")

                Spacer()

                // Position indicator
                VStack(spacing: 2) {
                    if let chapter = currentChapter {
                        Text(chapter.title)
                            .font(.caption)
                            .foregroundStyle(.primary)
